import crypto from 'node:crypto';
import { test, expect } from '../support/fixtures';
import { OwnerFormPage, ownerData } from '../pages/owner-pages';
import { PetFormPage, PetDetailsComponent } from '../pages/pet-pages';
import { VisitPage } from '../pages/visit-page';

test("E2E-020 Create and edit pet", async ({ page, evidence }) => {
  const owner = new OwnerFormPage(page);
  const detail = new PetDetailsComponent(page);
  const pet = new PetFormPage(page);
  const visit = new VisitPage(page);
  const ownerValues = ownerData(crypto.randomUUID().replaceAll('-', '').slice(0, 15));
  await evidence.step("E2E-020", "E2E-020-01", "Open new owner form", async () => { await owner.openNew(); });
  await evidence.assert("E2E-020", "E2E-020-01", "Owner form is visible — await expect(owner.heading).toBeVisible();", async () => { await expect(owner.heading).toBeVisible(); }, async () => owner.heading.textContent());
  await evidence.step("E2E-020", "E2E-020-02", "Enter unique owner data", async () => { await owner.enterOwner(ownerValues); });
  await evidence.assert("E2E-020", "E2E-020-02", "Last name retains unique input — await expect(owner.fields.lastName).toHaveValue(ownerValues.lastName);", async () => { await expect(owner.fields.lastName).toHaveValue(ownerValues.lastName); }, async () => owner.fields.lastName.inputValue());
  await evidence.step("E2E-020", "E2E-020-03", "Create isolated owner", async () => { await owner.submit(); });
  await evidence.assert("E2E-020", "E2E-020-03", "Owner details include unique surname — await expect(detail.heading).toBeVisible();", async () => { await expect(detail.heading).toBeVisible(); }, async () => detail.heading.textContent());
  await evidence.assert("E2E-020", "E2E-020-03", "Owner details include unique surname — await expect(page).toHaveURL(/\\/owners\\/\\d+(?:;jsessionid=[\\w]+)?$/);", async () => { await expect(page).toHaveURL(/\/owners\/\d+(?:;jsessionid=[\w]+)?$/); }, async () => ({ url: page.url() }));
  await evidence.step("E2E-020", "E2E-020-04", "Open Add New Pet", async () => { await detail.addPet(); });
  await evidence.assert("E2E-020", "E2E-020-04", "New Pet form is visible — await expect(pet.heading).toBeVisible();", async () => { await expect(pet.heading).toBeVisible(); }, async () => pet.heading.textContent());
  await evidence.step("E2E-020", "E2E-020-05", "Enter pet name, birth date and type", async () => { await pet.enterPet({"name":"Alpha","birthDate":"2020-01-02","type":"dog"}); });
  await evidence.assert("E2E-020", "E2E-020-05", "Pet inputs retain supplied values — await expect(pet.name).toHaveValue(\"Alpha\");", async () => { await expect(pet.name).toHaveValue("Alpha"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-020", "E2E-020-05", "Pet inputs retain supplied values — await expect(pet.birthDate).toHaveValue(\"2020-01-02\");", async () => { await expect(pet.birthDate).toHaveValue("2020-01-02"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-020", "E2E-020-05", "Pet inputs retain supplied values — await expect(pet.type).toHaveValue(\"dog\");", async () => { await expect(pet.type).toHaveValue("dog"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.step("E2E-020", "E2E-020-06", "Submit new pet", async () => { await pet.submit(); });
  await evidence.assert("E2E-020", "E2E-020-06", "Pet is persisted in owner details — await expect(detail.pet(\"Alpha\")).toContainText('2020-01-02');", async () => { await expect(detail.pet("Alpha")).toContainText('2020-01-02'); }, async () => await detail.pets.allTextContents());
  await evidence.step("E2E-020", "E2E-020-07", "Open Edit Pet", async () => { await detail.editPet("Alpha"); });
  await evidence.assert("E2E-020", "E2E-020-07", "Pet form is prefilled — await expect(pet.name).toHaveValue(\"Alpha\");", async () => { await expect(pet.name).toHaveValue("Alpha"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.step("E2E-020", "E2E-020-08", "Enter pet name, birth date and type", async () => { await pet.enterPet({"name":"Beta","birthDate":"2021-03-04","type":"cat"}); });
  await evidence.assert("E2E-020", "E2E-020-08", "Pet inputs retain supplied values — await expect(pet.name).toHaveValue(\"Beta\");", async () => { await expect(pet.name).toHaveValue("Beta"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-020", "E2E-020-08", "Pet inputs retain supplied values — await expect(pet.birthDate).toHaveValue(\"2021-03-04\");", async () => { await expect(pet.birthDate).toHaveValue("2021-03-04"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.assert("E2E-020", "E2E-020-08", "Pet inputs retain supplied values — await expect(pet.type).toHaveValue(\"cat\");", async () => { await expect(pet.type).toHaveValue("cat"); }, async () => ({ name: await pet.name.inputValue(), birthDate: await pet.birthDate.inputValue(), type: await pet.type.inputValue() }));
  await evidence.step("E2E-020", "E2E-020-09", "Update pet", async () => { await pet.submit(); });
  await evidence.assert("E2E-020", "E2E-020-09", "Updated pet details persist — await expect(detail.pet(\"Beta\")).toContainText(\"2021-03-04\");", async () => { await expect(detail.pet("Beta")).toContainText("2021-03-04"); }, async () => await detail.pets.allTextContents());
  await evidence.assert("E2E-020", "E2E-020-09", "Updated pet details persist — await expect(detail.pet(\"Beta\")).toContainText(\"cat\");", async () => { await expect(detail.pet("Beta")).toContainText("cat"); }, async () => await detail.pets.allTextContents());
});

